// ---- CONFIG: edit these, or set as Node-RED env vars with the same names ----
const ERP_BASE_URL = env.get('ERP_BASE_URL') || 'http://frontend:8080';
const ERP_API_KEY = env.get('ERP_API_KEY') || '963647fef4e3160';
const ERP_API_SECRET = env.get('ERP_API_SECRET') || 'ca26dff8278a440';
const DEFAULT_WAREHOUSE = env.get('ERP_DEFAULT_WAREHOUSE') || 'Stores - SD';

msg.erp = {
    baseUrl: ERP_BASE_URL,
    authHeader: 'token ' + ERP_API_KEY + ':' + ERP_API_SECRET
};

// ---- CSV ROW MAPPING ----
// TODO: once the supplier's real CSV headers are known, update the
// row.xxx field names below to match them exactly (case-sensitive).
const row = msg.payload;

msg.item = {
    item_code: row.item_code,
    csv_qty: Number(row.qty),
    warehouse: row.warehouse || DEFAULT_WAREHOUSE
};

if (!msg.item.item_code || isNaN(msg.item.csv_qty)) {
    node.warn('Skipping row with missing item_code or invalid qty: ' + JSON.stringify(row));
    return null;
}

return msg;
